import "server-only";
import { StoredUpload } from "@/models";
import { UPLOAD_FOLDERS, type UploadFolder } from "@/lib/fields";

const UPLOAD_PREFIX = "/api/uploads/";
const FILENAME_RE = /^[0-9]{10,16}-[a-f0-9]{8,64}\.(png|jpe?g|webp|gif)$/;

export function isAllowedFolder(folder: string): folder is UploadFolder {
  return (UPLOAD_FOLDERS as readonly string[]).includes(folder);
}

/** Rejects traversal and anything that is not a filename generated by /api/upload. */
export function isSafeFilename(filename: string): boolean {
  if (!filename || filename.length > 120) return false;
  if (filename.includes("..") || filename.includes("/") || filename.includes("\\")) return false;
  return FILENAME_RE.test(filename);
}

export function parseUploadUrl(url: unknown): { folder: UploadFolder; filename: string } | null {
  if (typeof url !== "string" || !url.startsWith(UPLOAD_PREFIX)) return null;
  const rest = url.slice(UPLOAD_PREFIX.length).split(/[?#]/)[0];
  const parts = rest.split("/");
  if (parts.length !== 2) return null;
  const [folder, filename] = parts;
  if (!isAllowedFolder(folder) || !isSafeFilename(filename)) return null;
  return { folder, filename };
}

/**
 * Deletes the MongoDB-stored image behind an /api/uploads/... URL.
 * External URLs (e.g. Unsplash) and static /images paths are ignored.
 */
export async function deleteStoredUploadByUrl(url: unknown): Promise<boolean> {
  const parsed = parseUploadUrl(url);
  if (!parsed) return false;
  try {
    const result = await StoredUpload.deleteOne(parsed);
    return result.deletedCount > 0;
  } catch (error) {
    console.error("[uploads] delete failed:", (error as Error).message);
    return false;
  }
}

/** Collects every stored-upload URL referenced anywhere inside a value. */
export function collectUploadUrls(value: unknown, found = new Set<string>()): Set<string> {
  if (typeof value === "string") {
    if (value.startsWith(UPLOAD_PREFIX)) found.add(value);
    // Rich text may embed uploaded images inside HTML.
    else if (value.includes(UPLOAD_PREFIX)) {
      for (const m of value.matchAll(/\/api\/uploads\/[a-z]+\/[A-Za-z0-9.-]+/g)) found.add(m[0]);
    }
  } else if (Array.isArray(value)) {
    for (const item of value) collectUploadUrls(item, found);
  } else if (value && typeof value === "object") {
    for (const item of Object.values(value)) collectUploadUrls(item, found);
  }
  return found;
}

const PAGE_IMAGE_KEYS = [
  "heroImage", "aboutImage", "aboutSecondaryImage", "ctaImage",
  "introImage", "introSecondaryImage", "missionImage",
];

/**
 * True if any saved content still references the upload. Prevents deleting an
 * image that the same admin reused elsewhere (e.g. copied from Media).
 */
export async function isUploadInUse(url: string): Promise<boolean> {
  const { Service, TeamMember, Testimonial, BlogPost, GalleryItem, Page, SiteSetting } = await import("@/models");
  const inHtml = new RegExp(url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const checks = await Promise.all([
    Service.exists({ image: url }),
    TeamMember.exists({ image: url }),
    Testimonial.exists({ image: url }),
    GalleryItem.exists({ image: url }),
    BlogPost.exists({ $or: [{ featuredImage: url }, { content: inHtml }] }),
    Page.exists({ $or: PAGE_IMAGE_KEYS.map((k) => ({ [`content.${k}`]: url })) }),
    SiteSetting.exists({ $or: [{ "data.logo": url }, { "data.ogImage": url }, { "data.insurers.logo": url }] }),
  ]);
  return checks.some(Boolean);
}

async function deleteIfUnused(url: string): Promise<void> {
  try {
    if (!(await isUploadInUse(url))) await deleteStoredUploadByUrl(url);
  } catch (error) {
    console.error("[uploads] cleanup failed:", (error as Error).message);
  }
}

/**
 * Call after saving an update: removes uploads that the previous version
 * referenced but the new version no longer uses (replaced or removed images).
 */
export async function cleanupReplacedUploads(before: unknown, after: unknown): Promise<void> {
  const previous = collectUploadUrls(before);
  const current = collectUploadUrls(after);
  await Promise.all([...previous].filter((url) => !current.has(url)).map(deleteIfUnused));
}

/** Call after deleting a document: removes its uploads unless used elsewhere. */
export async function deleteAllUploadsIn(value: unknown): Promise<void> {
  await Promise.all([...collectUploadUrls(value)].map(deleteIfUnused));
}
